/** Todos os perfis, histórias, características e estados abaixo são fictícios. */
export const cats: Cat[] = entries.map(
  (
    [
      nome,
      slug,
      sexo,
      pelagem,
      faixaEtaria,
      sociabilidade,
      brincadeira,
      carinho,
      status,
      descricaoCurta,
    ],
    i,
  ) => ({
    id: `demo-${slug}`,
    slug,
    nome,
    sexo,
    pelagem,
    faixaEtaria,
    idadeEstimada: faixaEtaria ? ageText[faixaEtaria] : null,
    descricaoCurta,
    historia: `${descricaoCurta} Nesta história fictícia, ${nome} faz parte de uma pequena colônia e está aprendendo a compartilhar a rotina com as pessoas que cuidam dela. Cada encontro acontece no seu tempo, com respeito ao seu espaço. Um ambiente seguro, paciência e cuidado fazem parte do próximo capítulo que imaginamos para ${nome}.`,
    sociabilidade,
    brincadeira,
    carinho,
    fotos:
      i === 9
        ? []
        : [
            {
              src: `/images/cats/${coatImages[pelagem]}.svg`,
              alt: `Ilustração demonstrativa de ${nome}, gato de pelagem ${pelagem.toLowerCase()}`,
            },
            {
              src: `/images/cats/${coatImages[pelagem]}-cozy.svg`,
              alt: `Ilustração demonstrativa de ${nome} em um cantinho aconchegante`,
            },
          ],
    status,
    castrado: faixaEtaria === "Filhote" ? null : i === 9 ? null : true,
    vacinado: i % 3 === 0 ? true : null,
    vermifugado: i % 2 === 0 ? true : null,
    necessidadesEspeciais: null,
    observacoesSaude: null,
    conviveComGatos: i % 3 === 0 ? true : null,
    conviveComCaes: null,
    conviveComCriancas: null,
    destaque: i < 3,
    dataAtualizacao: "2026-10-09",
  }),
);
